META = dict(nama="Railway", jp="鉄道", emoji="🚆", co="鉄道会社")
SPEC = dict(kerja="安全と時間の正確さをとても大切にしている", kerja_id="sangat mengutamakan keselamatan dan ketepatan waktu", soal={
 "shibou-01": ("なぜ鉄道の仕事を選びましたか。", "Mengapa Anda memilih pekerjaan perkeretaapian?", "小さいころから電車が好きでした。たくさんの人の毎日の生活を支える仕事がしたいです。", "Sejak kecil saya suka kereta. Saya ingin bekerja menopang kehidupan sehari-hari banyak orang.", [("鉄道", "perkeretaapian"), ("電車", "kereta listrik"), ("生活", "kehidupan"), ("支える", "menopang")]),
 "shibou-02": ("なぜ日本で鉄道の仕事を学びたいですか。", "Mengapa Anda ingin belajar perkeretaapian di Jepang?", "日本の電車は、時間がとても正確で、安全だと聞きました。その技術や考え方を学びたいです。", "Saya dengar kereta Jepang sangat tepat waktu dan aman. Saya ingin mempelajari teknologi dan cara berpikirnya.", [("正確", "akurat/tepat"), ("技術", "teknologi"), ("安全", "aman")]),
 "shibou-04": ("この仕事に興味を持った理由は何ですか。", "Apa alasan Anda tertarik pada pekerjaan ini?", "毎日、電車が安全に走るために、たくさんの人が働いています。その一人になって、役に立ちたいです。", "Setiap hari banyak orang bekerja agar kereta berjalan aman. Saya ingin menjadi salah satunya dan berguna.", [("走る", "berjalan"), ("役に立つ", "berguna"), ("興味", "minat")]),
 "shibou-05": ("鉄道の仕事で、一番楽しみなことは何ですか。", "Apa yang paling Anda nantikan dari pekerjaan perkeretaapian?", "自分が整備した電車や線路を、たくさんの人が安全に使ってくれることです。日本の技術も学びたいです。", "Kereta atau rel yang saya rawat dipakai banyak orang dengan aman. Saya juga ingin belajar teknologi Jepang.", [("線路", "rel"), ("整備", "perawatan"), ("楽しみ", "dinantikan")]),
 "shigoto-01": ("鉄道の整備の主な仕事は何だと思いますか。", "Menurut Anda, apa pekerjaan utama perawatan kereta?", "線路や、電気の設備、電車を点検して、直す仕事だと思います。電車が安全に走るための仕事です。", "Saya kira pekerjaannya memeriksa dan memperbaiki rel, peralatan listrik, dan kereta. Ini pekerjaan agar kereta berjalan aman.", [("点検", "inspeksi"), ("線路", "rel"), ("設備", "peralatan")]),
 "shigoto-02": ("夜遅くや、朝早くに働くことはできますか。", "Bisakah Anda bekerja larut malam atau pagi buta?", "はい、できます。電車が走っていない夜に、作業をすることが多いと聞きました。生活のリズムを作ります。", "Ya, bisa. Saya dengar pekerjaan sering dilakukan malam hari saat kereta tidak beroperasi. Saya akan membuat ritme hidup yang teratur.", [("夜間", "malam hari"), ("リズム", "ritme"), ("体調", "kondisi badan")]),
 "shigoto-03": ("暑い日や寒い日や雨の日でも、外で働けますか。", "Bisakah Anda bekerja di luar walau panas, dingin, atau hujan?", "はい、大丈夫です。暑い日はこまめに水を飲んで、寒い日は服をたくさん着ます。", "Ya, tidak masalah. Saat panas saya sering minum air dan saat dingin memakai banyak lapis pakaian.", [("暑い", "panas"), ("寒い", "dingin"), ("雨", "hujan")]),
 "shigoto-04": ("夜に働いて、昼に寝る生活になっても大丈夫ですか。", "Apakah Anda baik-baik saja bila hidup bekerja malam dan tidur siang?", "はい、大丈夫です。寝る時間をきちんと取って、食事にも気をつけます。", "Ya, tidak masalah. Saya mengatur waktu tidur dengan benar dan memperhatikan makan.", [("夜勤", "kerja malam"), ("睡眠", "tidur"), ("生活リズム", "ritme hidup")]),
 "shigoto-05": ("体力が必要な仕事ですが、大丈夫ですか。", "Pekerjaan ini butuh stamina, apakah Anda baik-baik saja?", "はい、大丈夫です。毎日運動をして、体力をつけています。重い道具は、一人で持たないようにします。", "Ya, tidak masalah. Saya berolahraga setiap hari. Alat berat tidak saya angkat sendirian.", [("体力", "stamina"), ("重い", "berat"), ("道具", "alat")]),
 "shigoto-06": ("時間が決まっている作業で、遅れそうなとき、どうしますか。", "Apa yang Anda lakukan kalau pekerjaan berbatas waktu sepertinya akan terlambat?", "あせらないで、すぐに責任者に報告します。時間より、安全と正確さが大切だと思います。", "Saya tidak panik dan segera melapor kepada penanggung jawab. Menurut saya keselamatan dan ketepatan lebih penting daripada waktu.", [("遅れる", "terlambat"), ("報告", "melapor"), ("正確", "akurat")]),
 "shigoto-07": ("線路の近くで作業するとき、何に気をつけますか。", "Apa yang Anda perhatikan saat bekerja di dekat rel?", "電車が来ないことを、責任者に確認してから入ります。見張りの人の合図を、必ず守ります。", "Saya masuk setelah memastikan kepada penanggung jawab bahwa kereta tidak datang. Saya selalu mematuhi isyarat petugas pengawas.", [("線路", "rel"), ("見張り", "pengawas"), ("合図", "isyarat")]),
 "shigoto-08": ("騒音や、油の汚れがある環境でも大丈夫ですか。", "Apakah Anda baik-baik saja di lingkungan bising dan kotor oli?", "はい、大丈夫です。必要なときは、耳せんやマスクをつけます。作業のあとで、手や体を洗います。", "Ya, tidak masalah. Bila perlu saya memakai penyumbat telinga dan masker. Setelah bekerja saya mencuci tangan dan badan.", [("騒音", "kebisingan"), ("油", "oli"), ("耳せん", "penyumbat telinga")]),
 "shigoto-09": ("鉄道の仕事で、大切なことは何だと思いますか。", "Menurut Anda, apa yang penting dalam pekerjaan perkeretaapian?", "安全と、確認を忘れないことだと思います。小さい間違いが、大きい事故になることがあるからです。", "Menurut saya, keselamatan dan tidak lupa memeriksa. Karena kesalahan kecil bisa menjadi kecelakaan besar.", [("安全", "keselamatan"), ("確認", "pengecekan"), ("事故", "kecelakaan")]),
 "shigoto-10": ("点検の仕事は、どのように進めますか。", "Bagaimana pekerjaan inspeksi dijalankan?", "チェック表を見ながら、順番に確認します。問題を見つけたら、すぐに先輩に報告します。", "Saya memeriksa berurutan sambil melihat daftar periksa. Kalau menemukan masalah, saya segera melapor kepada senior.", [("チェック表", "daftar periksa"), ("順番", "urutan"), ("報告", "melapor")]),
 "shigoto-11": ("「指差呼称」という言葉を知っていますか。", "Apakah Anda tahu istilah \"shisa kōshō\" (menunjuk dan menyebutkan)?", "指で差して、声に出して確認することだと聞きました。ミスを防ぐために、とても大切な方法だと思います。", "Saya dengar itu memeriksa dengan menunjuk dan menyebutkan dengan suara. Menurut saya cara ini penting untuk mencegah kesalahan.", [("指差呼称", "menunjuk dan menyebut"), ("確認", "memastikan"), ("ミス", "kesalahan")]),
 "shigoto-12": ("道具や部品の数を、確認することはできますか。", "Apakah Anda bisa memeriksa jumlah alat dan suku cadang?", "はい、できます。作業の前と後に、数を数えて、書いて記録します。忘れ物を、線路に残しません。", "Ya, bisa. Sebelum dan sesudah kerja saya menghitung dan mencatatnya. Saya tidak meninggalkan barang tertinggal di rel.", [("数える", "menghitung"), ("記録", "pencatatan"), ("忘れ物", "barang tertinggal")]),
 "shigoto-13": ("お客様や、まわりの人への配慮で、大切なことは何ですか。", "Apa yang penting dalam memperhatikan pelanggan dan orang sekitar?", "夜の作業では、音に気をつけます。近くの人の迷惑にならないように、大きい声や音を出しすぎません。", "Dalam kerja malam saya memperhatikan suara. Agar tidak mengganggu warga sekitar, saya tidak membuat suara terlalu keras.", [("迷惑", "gangguan"), ("音", "suara"), ("配慮", "pertimbangan")]),
 "taiou-02": ("点検で、ミスに気づいたら、どうしますか。", "Apa yang Anda lakukan kalau menyadari kesalahan dalam inspeksi?", "すぐに正直に報告します。どうしてそうなったか考えて、次は確認を一回多くします。", "Saya segera melapor jujur. Saya memikirkan penyebabnya dan lain kali menambah satu kali pengecekan.", [("ミス", "kesalahan"), ("報告", "melapor"), ("確認", "pengecekan")]),
 "taiou-06": ("急に、作業の時間や内容が変わったら、どうしますか。", "Apa yang Anda lakukan kalau waktu atau isi pekerjaan berubah mendadak?", "責任者の指示をよく聞いて、新しい作業を始めます。分からないときは、すぐに聞きます。", "Saya mendengarkan instruksi penanggung jawab dan memulai pekerjaan baru. Kalau tidak paham, saya langsung bertanya.", [("急に", "mendadak"), ("指示", "instruksi"), ("内容", "isi")]),
 "taiou-08": ("災害や事故で、電車が止まったとき、どうしますか。", "Apa yang Anda lakukan kalau kereta berhenti karena bencana atau kecelakaan?", "自分で判断しないで、責任者の指示を待ちます。指示のとおりに、安全に動きます。", "Saya tidak memutuskan sendiri dan menunggu instruksi penanggung jawab. Saya bergerak dengan aman sesuai instruksi.", [("災害", "bencana"), ("判断", "keputusan"), ("指示", "instruksi")]),
 "taiou-11": ("夜の作業で疲れているとき、どう気持ちを保ちますか。", "Bagaimana Anda menjaga semangat saat lelah dalam kerja malam?", "休けいの時間に、しっかり休みます。食事と睡眠に気をつけて、体調を保ちます。", "Saat istirahat saya benar-benar beristirahat. Saya menjaga makan dan tidur untuk menjaga kondisi badan.", [("疲れる", "lelah"), ("休けい", "istirahat"), ("体調", "kondisi badan")]),
 "taiou-12": ("先輩が専門用語で説明して、分からないとき、どうしますか。", "Apa yang Anda lakukan kalau senior menjelaskan dengan istilah teknis dan Anda tidak paham?", "「すみません、この言葉の意味を教えてください」と聞きます。メモして、あとで復習します。", "Saya bertanya \"Maaf, tolong jelaskan arti kata ini\". Saya mencatatnya dan mengulang pelajaran nanti.", [("専門用語", "istilah teknis"), ("意味", "arti"), ("復習", "mengulang pelajaran")]),
 "tim-01": ("夜の作業で、チームの人と、どのように作業を分けますか。", "Dalam kerja malam, bagaimana Anda membagi tugas dengan tim?", "責任者の指示で、点検する人、直す人、見張りの人などに分かれます。声をかけ合って、安全に作業します。", "Sesuai instruksi penanggung jawab, ada yang memeriksa, memperbaiki, dan mengawasi. Kami saling memberi aba-aba agar aman.", [("分担", "pembagian tugas"), ("見張り", "pengawas"), ("声をかけ合う", "saling memberi aba-aba")]),
 "tim-02": ("先輩の指示が分からなかったとき、どうしますか。", "Apa yang Anda lakukan kalau tidak paham instruksi senior?", "すぐに「もう一度お願いします」と聞きます。分からないまま作業すると、事故につながるからです。", "Saya segera meminta \"Tolong ulangi\". Bekerja tanpa paham bisa menyebabkan kecelakaan.", [("指示", "instruksi"), ("事故", "kecelakaan"), ("確認", "memastikan")]),
 "tim-03": ("作業の前と後に、チームで、どんなことを確認しますか。", "Apa yang dikonfirmasi tim sebelum dan sesudah pekerjaan?", "作業の前に、作業の内容と、危ない場所を確認します。作業のあとに、道具の数と、問題がないか確認します。", "Sebelum kerja kami memastikan isi pekerjaan dan tempat berbahaya. Setelah kerja kami memeriksa jumlah alat dan ada tidaknya masalah.", [("打ち合わせ", "rapat singkat"), ("危険", "bahaya"), ("確認", "memastikan")]),
 "tim-04": ("会社の仲間と、どのように仲良くなりたいですか。", "Bagaimana Anda ingin akrab dengan rekan di perusahaan?", "毎日、元気にあいさつをします。教えてもらったときは、「ありがとうございます」と言います。", "Setiap hari saya menyapa dengan semangat. Saat diajari, saya mengatakan \"Terima kasih\".", [("あいさつ", "salam"), ("仲間", "rekan"), ("仲良くなる", "menjadi akrab")]),
 "anzen-01": ("線路や、電車の近くで、必ず身につけるものは何ですか。", "Apa yang wajib dikenakan di dekat rel atau kereta?", "ヘルメット、安全靴、反射する安全ベストを必ず着けます。夜は、ライトも使います。", "Saya wajib memakai helm, sepatu keselamatan, dan rompi keselamatan reflektif. Pada malam hari saya juga memakai lampu.", [("安全ベスト", "rompi keselamatan"), ("反射", "memantulkan cahaya"), ("ヘルメット", "helm")]),
 "anzen-02": ("線路の上で作業するとき、何をしますか。", "Apa yang Anda lakukan saat bekerja di atas rel?", "電車が止まったことを、責任者に確認してから入ります。見張りの人の合図を、必ず守ります。", "Saya masuk setelah memastikan kepada penanggung jawab bahwa kereta berhenti. Saya selalu mematuhi isyarat pengawas.", [("見張り", "pengawas"), ("合図", "isyarat"), ("確認", "memastikan")]),
 "anzen-03": ("電気の設備を扱うとき、何に気をつけますか。", "Apa yang Anda perhatikan saat menangani peralatan listrik?", "必ず電気が切れていることを、確認します。確認しないで、さわりません。勝手に作業しません。", "Saya selalu memastikan listrik sudah padam. Saya tidak menyentuhnya tanpa memastikan. Saya tidak bekerja sembarangan.", [("感電", "tersengat listrik"), ("確認", "memastikan"), ("電気", "listrik")]),
 "anzen-04": ("もし、線路の近くで、あぶないと思ったら、どうしますか。", "Apa yang Anda lakukan kalau merasa berbahaya di dekat rel?", "すぐに作業をやめて、責任者に知らせます。「大丈夫だろう」と思わないで、必ず確認します。", "Saya segera menghentikan pekerjaan dan memberi tahu penanggung jawab. Saya tidak berpikir \"mungkin aman\", tetapi selalu memeriksa.", [("作業をやめる", "menghentikan pekerjaan"), ("知らせる", "memberi tahu"), ("確認", "memastikan")]),
 "seikatsu-07": ("夜の仕事で、生活の時間が普通と違っても大丈夫ですか。", "Apakah Anda baik-baik saja bila jam hidup berbeda dari orang biasa karena kerja malam?", "大丈夫です。カーテンを閉めて、静かな部屋でしっかり寝ます。買い物や勉強は、起きている時間にします。", "Tidak masalah. Saya menutup gorden dan tidur nyenyak di kamar yang tenang. Belanja dan belajar saya lakukan saat terjaga.", [("夜勤", "kerja malam"), ("睡眠", "tidur"), ("生活", "kehidupan")]),
 "seikatsu-08": ("日本の電車や、駅の文化について、知っていることはありますか。", "Apa yang Anda ketahui tentang kereta dan budaya stasiun di Jepang?", "日本の電車は、時間がとても正確だと聞きました。みんなが並んで待つことや、車内で静かにすることも知っています。", "Saya dengar kereta Jepang sangat tepat waktu. Saya juga tahu orang mengantre dan tenang di dalam kereta.", [("並ぶ", "mengantre"), ("車内", "di dalam kereta"), ("マナー", "tata krama")]),
 "mokuhyou-05": ("日本で鉄道の仕事を学んだあと、自分の国でどんなことをしたいですか。", "Setelah belajar perkeretaapian di Jepang, apa yang ingin Anda lakukan di negara sendiri?", "日本で学んだ点検の方法と、安全の考え方を使って、自分の国の鉄道の仕事をしたいです。", "Saya ingin bekerja di perkeretaapian negara saya dengan memakai cara inspeksi dan cara berpikir keselamatan yang saya pelajari di Jepang.", [("点検", "inspeksi"), ("安全", "keselamatan"), ("考え方", "cara berpikir")]),
})
